insert into public.engagement_messages values ('tip-001','فكرة لعمارة أرتب 🏡','صاحبك ماسك إدارة عمارة؟ عرّفه على العمارة وسهّل عليه متابعة السكان.');
insert into public.engagement_messages values ('tip-002','فكرة لعمارة أرتب 🏡','التحصيل بيحتاج ترتيب. متابعة السداد أول بأول بتخلّي الصورة أوضح.');
insert into public.engagement_messages values ('tip-003','فكرة لعمارة أرتب 🏡','قرار يخص الجميع؟ اسمع رأي السكان قبل التنفيذ.');
insert into public.engagement_messages values ('tip-004','فكرة لعمارة أرتب 🏡','بلاغ الصيانة الواضح بيساعد الإدارة تفهم المشكلة أسرع.');
insert into public.engagement_messages values ('tip-005','فكرة لعمارة أرتب 🏡','إعلان بموعد انقطاع المياه بيدي الجيران فرصة يرتّبوا يومهم.');
insert into public.engagement_messages values ('tip-006','فكرة لعمارة أرتب 🏡','لما رقم حارس العقار يبقى معروف، الوصول له وقت الحاجة بيبقى أسهل.');
insert into public.engagement_messages values ('tip-007','فكرة لعمارة أرتب 🏡','تسجيل المصروف في وقته أوفر من محاولة تذكّره آخر الشهر.');
insert into public.engagement_messages values ('tip-008','فكرة لعمارة أرتب 🏡','مشاركة أخبار العمارة في مكان واحد بتقلّل الرسائل المتفرقة.');
insert into public.engagement_messages values ('tip-009','فكرة لعمارة أرتب 🏡','لو جارك لسه ما انضمش، عرّفه على كود العمارة وخليه متابع.');
insert into public.engagement_messages values ('tip-010','فكرة لعمارة أرتب 🏡','راجع بيانات شقتك عشان كل متابعة تكون مرتبطة بالمكان الصح.');
insert into public.engagement_messages values ('tip-011','فكرة لعمارة أرتب 🏡','صيانة المصعد الدورية تستاهل متابعة قبل ما تحصل مشكلة.');
insert into public.engagement_messages values ('tip-012','فكرة لعمارة أرتب 🏡','إيصال السداد بيريّح السكان والإدارة من لخبطة الحسابات.');
insert into public.engagement_messages values ('tip-013','فكرة لعمارة أرتب 🏡','اعرض تفاصيل القرار بوضوح عشان التصويت يبقى على أساس مفهوم.');
insert into public.engagement_messages values ('tip-014','فكرة لعمارة أرتب 🏡','التواصل الهادي بيسهّل حل الخلافات بين الجيران.');
insert into public.engagement_messages values ('tip-015','فكرة لعمارة أرتب 🏡','ترتيب المصروفات حسب نوعها بيسهّل فهم احتياجات العمارة.');
insert into public.engagement_messages values ('tip-016','فكرة لعمارة أرتب 🏡','خبر تنظيف الخزان مهم لكل السكان. خلّيهم يعرفوا معاده بدري.');
insert into public.engagement_messages values ('tip-017','فكرة لعمارة أرتب 🏡','متابعة بلاغ قديم مهمة زي تسجيل بلاغ جديد.');
insert into public.engagement_messages values ('tip-018','فكرة لعمارة أرتب 🏡','قبل ما تسدد، راجع بيانات الدفع المعتمدة من إدارة عمارتك.');
insert into public.engagement_messages values ('tip-019','فكرة لعمارة أرتب 🏡','الحفاظ على المداخل نظيفة مسؤولية بنشارك فيها كلنا.');
insert into public.engagement_messages values ('tip-020','فكرة لعمارة أرتب 🏡','صديقك بيجمع الاشتراكات في دفتر؟ ورّيه طريقة متابعة العمارة.');
insert into public.engagement_messages values ('tip-021','فكرة لعمارة أرتب 🏡','تحديد موعد واضح للتحصيل بيساعد كل ساكن يرتّب التزاماته.');
insert into public.engagement_messages values ('tip-022','فكرة لعمارة أرتب 🏡','بلاغ فيه مكان العطل أدق من بلاغ بيقول فيه مشكلة وبس.');
insert into public.engagement_messages values ('tip-023','فكرة لعمارة أرتب 🏡','خلي قرارات العمارة مكتوبة عشان نرجعلها وقت اللزوم.');
insert into public.engagement_messages values ('tip-024','فكرة لعمارة أرتب 🏡','الأرقام الواضحة بتبني ثقة بين الإدارة والسكان.');
insert into public.engagement_messages values ('tip-025','فكرة لعمارة أرتب 🏡','راجع الإعلانات قبل ما تسأل، ممكن تلاقي المعلومة مستنياك.');
insert into public.engagement_messages values ('tip-026','فكرة لعمارة أرتب 🏡','بداية شهر جديدة فرصة لمراجعة التزامات العمارة بهدوء.');
insert into public.engagement_messages values ('tip-027','فكرة لعمارة أرتب 🏡','لو غيرت رقم تليفونك، خلّي الإدارة تعرف وسيلة التواصل الجديدة.');
insert into public.engagement_messages values ('tip-028','فكرة لعمارة أرتب 🏡','صيانة بوابة الجراج بتخدم راحة وأمان كل مستخدميها.');
insert into public.engagement_messages values ('tip-029','فكرة لعمارة أرتب 🏡','مش لازم كل قرار يستنى اجتماع طويل. التصويت يساعد يسمع الآراء.');
insert into public.engagement_messages values ('tip-030','فكرة لعمارة أرتب 🏡','الإدارة المنظمة بتبدأ بمعلومة متسجلة في مكانها.');
insert into public.engagement_messages values ('tip-031','فكرة لعمارة أرتب 🏡','لو حد من معارفك استلم إدارة عقار، عرّفه على العمارة.');
insert into public.engagement_messages values ('tip-032','فكرة لعمارة أرتب 🏡','تنبيه بمواعيد أعمال الصيانة بيساعد السكان يتجنبوا الإزعاج.');
insert into public.engagement_messages values ('tip-033','فكرة لعمارة أرتب 🏡','فرّق بين العطل العاجل والملاحظة العادية عند تقديم البلاغ.');
insert into public.engagement_messages values ('tip-034','فكرة لعمارة أرتب 🏡','خليك متابع لحالة طلبك عشان تعرف آخر إجراء حصل.');
insert into public.engagement_messages values ('tip-035','فكرة لعمارة أرتب 🏡','اتفاق السكان على أولويات الصيانة بيسهّل اختيار البداية.');
insert into public.engagement_messages values ('tip-036','فكرة لعمارة أرتب 🏡','أرقام الطوارئ لازم تكون صحيحة ومعروفة قبل الاحتياج لها.');
insert into public.engagement_messages values ('tip-037','فكرة لعمارة أرتب 🏡','متابعة إنارة السلم خطوة بسيطة بتفرق في حركة السكان.');
insert into public.engagement_messages values ('tip-038','فكرة لعمارة أرتب 🏡','الشفافية في المصروفات بتقلّل سوء الفهم بين الجيران.');
insert into public.engagement_messages values ('tip-039','فكرة لعمارة أرتب 🏡','راجع قيمة الدفعة قبل تأكيدها عشان التسجيل يطلع مضبوط.');
insert into public.engagement_messages values ('tip-040','فكرة لعمارة أرتب 🏡','صورة كاملة عن العمارة بتتكوّن من تفاصيل صغيرة محفوظة.');
insert into public.engagement_messages values ('tip-041','فكرة لعمارة أرتب 🏡','مشرف عمارة في العيلة؟ ابعتله اسم التطبيق وخليه يتعرف عليه.');
insert into public.engagement_messages values ('tip-042','فكرة لعمارة أرتب 🏡','مواعيد الهدوء المتفق عليها بتخلّي السكن أريح للجميع.');
insert into public.engagement_messages values ('tip-043','فكرة لعمارة أرتب 🏡','الإعلان المختصر بعنوان واضح بيوصل أسرع من كلام كتير.');
insert into public.engagement_messages values ('tip-044','فكرة لعمارة أرتب 🏡','المشاركة في التصويت بتوصل رأيك بدل ما يفضل اقتراح ساكت.');
insert into public.engagement_messages values ('tip-045','فكرة لعمارة أرتب 🏡','الحجز المرتب للمرافق بيساعد الجيران يستخدموها براحة.');
insert into public.engagement_messages values ('tip-046','فكرة لعمارة أرتب 🏡','ملاحظة عن تسريب مياه النهارده ممكن تساعد تتجنب تلف أكبر.');
insert into public.engagement_messages values ('tip-047','فكرة لعمارة أرتب 🏡','تحديث بيانات الإدارة بيسهّل الوصول للشخص المسؤول.');
insert into public.engagement_messages values ('tip-048','فكرة لعمارة أرتب 🏡','راجع السداد المسجل عندك، وأي اختلاف بلّغ الإدارة بيه.');
insert into public.engagement_messages values ('tip-049','فكرة لعمارة أرتب 🏡','تنظيم طلبات الصيانة بيساعد ما ننساش البلاغات الأقل ظهورًا.');
insert into public.engagement_messages values ('tip-050','فكرة لعمارة أرتب 🏡','اتفاق واضح على استخدام الروف بيوفّر خلافات بعدين.');
insert into public.engagement_messages values ('tip-051','فكرة لعمارة أرتب 🏡','صاحبك شاطر في إدارة عمارات؟ يمكن التطبيق يسهّل عليه أكتر.');
insert into public.engagement_messages values ('tip-052','فكرة لعمارة أرتب 🏡','سجل سبب المصروف، مش رقمه بس، عشان يفضل مفهوم بعد فترة.');
insert into public.engagement_messages values ('tip-053','فكرة لعمارة أرتب 🏡','تنبيه بتغيير رقم المحفظة لازم يوصل للسكان قبل التحويل.');
insert into public.engagement_messages values ('tip-054','فكرة لعمارة أرتب 🏡','راجع حالة التصويت وموعد انتهائه قبل ما تأجل المشاركة.');
insert into public.engagement_messages values ('tip-055','فكرة لعمارة أرتب 🏡','الرد الواضح على بلاغ الصيانة بيطمن صاحب الطلب.');
insert into public.engagement_messages values ('tip-056','فكرة لعمارة أرتب 🏡','تقدير شغل الحارس مع وضوح مسؤولياته بيساعد الجميع.');
insert into public.engagement_messages values ('tip-057','فكرة لعمارة أرتب 🏡','تحديد مكان العطل: دور كام وشقة كام؟ معلومتين بيفرقوا.');
insert into public.engagement_messages values ('tip-058','فكرة لعمارة أرتب 🏡','بدل ما تفتكر المبلغ من الذاكرة، ارجع للسجل.');
insert into public.engagement_messages values ('tip-059','فكرة لعمارة أرتب 🏡','مشاركة نتائج التصويت بتخلّي القرار مفهوم للسكان.');
insert into public.engagement_messages values ('tip-060','فكرة لعمارة أرتب 🏡','تنظيم دخول مقدمي الصيانة بيريّح السكان والإدارة.');
insert into public.engagement_messages values ('tip-061','فكرة لعمارة أرتب 🏡','كل عمارة ليها تفاصيلها. البيانات الصحيحة بتخلي المتابعة مفيدة.');
insert into public.engagement_messages values ('tip-062','فكرة لعمارة أرتب 🏡','نقطة بداية واضحة للحسابات بتسهّل متابعة اللي حصل بعدها.');
insert into public.engagement_messages values ('tip-063','فكرة لعمارة أرتب 🏡','وديعة الصيانة محتاجة وضوح زي المصروفات اليومية.');
insert into public.engagement_messages values ('tip-064','فكرة لعمارة أرتب 🏡','وقت الاجتماع يبقى أنفع لما جدول المناقشة معروف مسبقًا.');
insert into public.engagement_messages values ('tip-065','فكرة لعمارة أرتب 🏡','اسأل الإدارة عن أي بند مش واضح بدل ما تخمّن معناه.');
insert into public.engagement_messages values ('tip-066','فكرة لعمارة أرتب 🏡','نظافة الممرات بتسهّل الحركة وبتحافظ على شكل المكان.');
insert into public.engagement_messages values ('tip-067','فكرة لعمارة أرتب 🏡','متابعة أعمال الصيانة بعد التنفيذ بتأكد إن المشكلة اتحلت.');
insert into public.engagement_messages values ('tip-068','فكرة لعمارة أرتب 🏡','مشاركة التطبيق مع مدير عمارة تاني ممكن تبدأ له طريقة أرتب.');
insert into public.engagement_messages values ('tip-069','فكرة لعمارة أرتب 🏡','لو الطلب اتسجل مرتين بالغلط، وضّح ده للإدارة.');
insert into public.engagement_messages values ('tip-070','فكرة لعمارة أرتب 🏡','التنبيه المهم بيكون أنفع لما عنوانه يوضح المقصود.');
insert into public.engagement_messages values ('tip-071','فكرة لعمارة أرتب 🏡','مراجعة رصيد العمارة بتساعد نفهم المتاح قبل اقتراح شغل جديد.');
insert into public.engagement_messages values ('tip-072','فكرة لعمارة أرتب 🏡','توزيع المسؤوليات بين الإدارة بيساعد كل طلب يوصل لمكانه.');
insert into public.engagement_messages values ('tip-073','فكرة لعمارة أرتب 🏡','إعلان عن أعمال الدهان بيدي السكان فرصة يحافظوا على حاجاتهم.');
insert into public.engagement_messages values ('tip-074','فكرة لعمارة أرتب 🏡','الاقتراح المحدد أسهل للمناقشة من شكوى عامة.');
insert into public.engagement_messages values ('tip-075','فكرة لعمارة أرتب 🏡','التحويلات تحتاج مراجعة بيانات المستلم في كل مرة.');
insert into public.engagement_messages values ('tip-076','فكرة لعمارة أرتب 🏡','بلاغ باب مش بيقفل كويس يستحق متابعة زي الأعطال الكبيرة.');
insert into public.engagement_messages values ('tip-077','فكرة لعمارة أرتب 🏡','وجود وصف واضح للشقة بيساعد الإدارة تتجنب تشابه الأسماء.');
insert into public.engagement_messages values ('tip-078','فكرة لعمارة أرتب 🏡','الاحترام في كتابة الملاحظات بيفتح باب أسرع للتعاون.');
insert into public.engagement_messages values ('tip-079','فكرة لعمارة أرتب 🏡','اختيار وقت مناسب لأعمال الحفر بيقلّل الإزعاج للجيران.');
insert into public.engagement_messages values ('tip-080','فكرة لعمارة أرتب 🏡','معلومة واحدة ناقصة ممكن تأخّر الحل. راجع تفاصيل البلاغ.');
insert into public.engagement_messages values ('tip-081','فكرة لعمارة أرتب 🏡','عرّف صاحبك على العمارة بكلمتين: متابعة أوضح وتنظيم أسهل.');
insert into public.engagement_messages values ('tip-082','فكرة لعمارة أرتب 🏡','الالتزام بمواعيد استخدام المرافق بيريّح الجار اللي بعدك.');
insert into public.engagement_messages values ('tip-083','فكرة لعمارة أرتب 🏡','راجع الملخص المالي قبل ما تبني عليه اقتراح جديد.');
insert into public.engagement_messages values ('tip-084','فكرة لعمارة أرتب 🏡','تصحيح الخطأ أول ما تلاحظه أفضل من تركه يتراكم.');
insert into public.engagement_messages values ('tip-085','فكرة لعمارة أرتب 🏡','التنسيق لتنظيف الجراج بيسهّل نقل العربيات في الموعد.');
insert into public.engagement_messages values ('tip-086','فكرة لعمارة أرتب 🏡','القرار المشترك بيحتاج فرصة عادلة للكل يعرفه ويشارك.');
insert into public.engagement_messages values ('tip-087','فكرة لعمارة أرتب 🏡','خلي إعلان الصيانة يوضح المكان والوقت المتوقع للعمل.');
insert into public.engagement_messages values ('tip-088','فكرة لعمارة أرتب 🏡','مراجعة الأسماء عند تسجيل السكان بتقلّل الالتباس.');
insert into public.engagement_messages values ('tip-089','فكرة لعمارة أرتب 🏡','السؤال عن حالة البلاغ يكون أوضح لما تحدد الطلب المقصود.');
insert into public.engagement_messages values ('tip-090','فكرة لعمارة أرتب 🏡','اعرض البدائل قبل التصويت لو القرار ليه أكتر من حل.');
insert into public.engagement_messages values ('tip-091','فكرة لعمارة أرتب 🏡','إدارة العمارة شغل جماعي، حتى المعلومة الصغيرة بتساعد.');
insert into public.engagement_messages values ('tip-092','فكرة لعمارة أرتب 🏡','جولة بسيطة على الإعلانات بتخليك عارف الجديد في عمارتك.');
insert into public.engagement_messages values ('tip-093','فكرة لعمارة أرتب 🏡','لو جار جديد وصل، ساعده يعرف طريقة متابعة أخبار العقار.');
insert into public.engagement_messages values ('tip-094','فكرة لعمارة أرتب 🏡','الوضوح في طريقة السداد بيوفّر أسئلة متكررة على الإدارة.');
insert into public.engagement_messages values ('tip-095','فكرة لعمارة أرتب 🏡','الاحتفاظ بوصف الفاتورة بيسهّل مراجعة المصروف بعدين.');
insert into public.engagement_messages values ('tip-096','فكرة لعمارة أرتب 🏡','التخطيط للصيانة قبل موسم المطر ممكن يجنّبكم مفاجآت.');
insert into public.engagement_messages values ('tip-097','فكرة لعمارة أرتب 🏡','تحديث حالة الحجز لما يتغيّر بيتيح الفرصة لساكن تاني.');
insert into public.engagement_messages values ('tip-098','فكرة لعمارة أرتب 🏡','مراجعة بلاغات الإنارة بتخلي المناطق المشتركة أريح للجميع.');
insert into public.engagement_messages values ('tip-099','فكرة لعمارة أرتب 🏡','قبل نقل إدارة العقار، رتّب المعلومات المهمة للمسؤول الجديد.');
insert into public.engagement_messages values ('tip-100','فكرة لعمارة أرتب 🏡','الخطوة الصغيرة النهارده: خلّي معلومة تخص عمارتك أوضح لغيرك.');
    insert into public.engagement_history values(p.id,msg.id,local_time::date,slot_number);
    insert into public.app_notifications(recipient_id,building_id,category,title,body,manager_target,member_target,source_key) values(p.id,p.building_id,'engagement',msg.title,msg.body,'dashboard','home','engagement:'||msg.id);
    insert into public.notification_deliveries(notification_id,device_id)
